package cn.zhuatech.spc;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepSpcOpsTests{@Autowired MockMvc mvc;String hash="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
 @Test void outOfControlSignalRunsThroughCapa()throws Exception{long c=characteristic("CTQ-1");admin("/api/admin/spc-ops/characteristics/"+c+"/activate","{}");MvcResult result=post("/api/spc-ops/characteristics/"+c+"/samples",sample("S-1",10.5)).andExpect(jsonPath("$.data.triggeredRule").value("RULE_1_BEYOND_3_SIGMA")).andReturn();long signal=idField(result,"signalId");post("/api/spc-ops/signals/"+signal+"/assign","{\"owner\":\"工艺工程师\"}");post("/api/spc-ops/signals/"+signal+"/corrective-action","{\"rootCause\":\"刀具磨损\",\"correctiveAction\":\"更换刀具并首件确认\",\"evidenceHash\":\""+hash+"\"}");admin("/api/admin/spc-ops/signals/"+signal+"/verify","{\"effective\":true,\"note\":\"连续五组恢复稳定\"}").andExpect(jsonPath("$.data.status").value("CLOSED"));}
 @Test void inactiveCharacteristicAndInvalidEvidenceAreBlocked()throws Exception{long c=characteristic("CTQ-2");post("/api/spc-ops/characteristics/"+c+"/samples",sample("S-X",10)).andExpect(status().isConflict());admin("/api/admin/spc-ops/characteristics/"+c+"/activate","{}");long signal=idField(post("/api/spc-ops/characteristics/"+c+"/samples",sample("S-2",10.5)).andReturn(),"signalId");post("/api/spc-ops/signals/"+signal+"/assign","{\"owner\":\"工程师\"}");post("/api/spc-ops/signals/"+signal+"/corrective-action","{\"rootCause\":\"待查\",\"correctiveAction\":\"调整\",\"evidenceHash\":\"bad\"}").andExpect(status().isBadRequest());}
 @Test void eightPointsOnOneSideTriggerShiftRule()throws Exception{long c=characteristic("CTQ-3");admin("/api/admin/spc-ops/characteristics/"+c+"/activate","{}");for(int i=0;i<7;i++)post("/api/spc-ops/characteristics/"+c+"/samples",sample("SHIFT-"+i,10.1));post("/api/spc-ops/characteristics/"+c+"/samples",sample("SHIFT-7",10.1)).andExpect(jsonPath("$.data.triggeredRule").value("RULE_2_EIGHT_ON_ONE_SIDE"));}
 long characteristic(String n)throws Exception{return id(post("/api/spc-ops/characteristics","{\"organizationCode\":\"ZH-SH\",\"characteristicCode\":\""+n+"\",\"name\":\"轴径\",\"unit\":\"mm\",\"targetValue\":10,\"lowerSpecLimit\":9.4,\"upperSpecLimit\":10.6,\"sigma\":0.1}").andReturn());}String sample(String n,double v){return "{\"sampleNo\":\""+n+"\",\"measuredValue\":"+v+",\"subgroup\":\"LINE-A\",\"sampledAt\":\"2026-09-01T10:00:00\"}";}ResultActions post(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content(b));}ResultActions admin(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("admin","admin123")).contentType(MediaType.APPLICATION_JSON).content(b));}long id(MvcResult r)throws Exception{return idField(r,"id");}long idField(MvcResult r,String field)throws Exception{var m=Pattern.compile("\""+field+"\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
